const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var u = W * 0.10;
    var barLeft = W * 0.18;
    var fx = barLeft + 2 * u;
    var barRight = barLeft + 7 * u;
    var groundY = H * 0.85;
    var barY = groundY - 0.95 * u;
    var barThick = 0.17 * u;
    var dimY = barY - 1.25 * u;
    var head = 0.20 * u;
    var guideWidth = Math.max(1.2, 0.03 * u);

    function poly(pts) {
      var c = [['M', pts[0][0], pts[0][1]]];
      var i;
      for (i = 1; i < pts.length; i = i + 1) {
        c.push(['L', pts[i][0], pts[i][1]]);
      }
      c.push(['Z']);
      return c;
    }

    function dim(xa, xb, y) {
      var c = [['M', xa, y], ['L', xb, y]];
      c.push(['M', xa + head, y - head * 0.42], ['L', xa, y], ['L', xa + head, y + head * 0.42]);
      c.push(['M', xb - head, y - head * 0.42], ['L', xb, y], ['L', xb - head, y + head * 0.42]);
      return c;
    }

    var rx0 = barLeft - 1.00 * u;
    var rockPts = [
      [rx0, groundY],
      [rx0 + 0.15 * u, groundY - 0.55 * u],
      [rx0 + 0.55 * u, groundY - 1.35 * u],
      [rx0 + 1.15 * u, groundY - 1.15 * u],
      [barLeft + 0.72 * u, groundY - 0.50 * u],
      [barLeft + 0.52 * u, groundY]
    ];

    var groundCmds = [['M', W * 0.03, groundY], ['L', W * 0.97, groundY]];
    var barCmds = [['M', barLeft, barY], ['L', barRight, barY]];
    var rockCmds = poly(rockPts);
    var fulcrumCmds = poly([
      [fx - 0.50 * u, groundY],
      [fx + 0.50 * u, groundY],
      [fx, barY + 0.04 * u]
    ]);
    var guideCmds = [
      ['M', barLeft, barY], ['L', barLeft, dimY],
      ['M', fx, barY], ['L', fx, dimY],
      ['M', barRight, barY - 0.95 * u], ['L', barRight, dimY]
    ];
    var dimCmds = dim(barLeft, fx, dimY).concat(dim(fx, barRight, dimY));
    var forceCmds = [
      ['M', barRight, barY - 0.80 * u],
      ['L', barRight, barY - 0.12 * u],
      ['M', barRight - 0.13 * u, barY - 0.34 * u],
      ['L', barRight, barY - 0.12 * u],
      ['L', barRight + 0.13 * u, barY - 0.34 * u]
    ];

    var midRes = (barLeft + fx) / 2;
    var midPow = (fx + barRight) / 2;
    var labelY = dimY - 0.18 * u;

    return {
      schemaVersion: 1,
      sceneId: 'crowbar-lever',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'ground', commands: groundCmds },
        { id: 'bar', commands: barCmds },
        { id: 'rock', commands: rockCmds },
        { id: 'fulcrum', commands: fulcrumCmds },
        { id: 'guides', commands: guideCmds },
        { id: 'dims', commands: dimCmds },
        { id: 'force', commands: forceCmds }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'ground', fill: '#7f8c99', stroke: { width: 2, cap: 'round' } },
        { type: 'path', pathId: 'bar', fill: '#55606e', stroke: { width: barThick, cap: 'round' } },
        { type: 'path', pathId: 'rock', fill: '#a9a49b', stroke: { width: 2, cap: 'round', join: 'round' } },
        { type: 'path', pathId: 'fulcrum', fill: '#c9772f', stroke: { width: 2, cap: 'round', join: 'round' } },
        { type: 'path', pathId: 'guides', fill: '#9aa8b6', stroke: { width: guideWidth, cap: 'round' } },
        { type: 'path', pathId: 'dims', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
        { type: 'path', pathId: 'force', fill: '#c0392b', stroke: { width: 3, cap: 'round', join: 'round' } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: fx + 0.75 * u, y: groundY - 0.10 * u }, hAlign: 'left', vAlign: 'bottom', color: '#1f2d3d' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: midPow, y: labelY }, hAlign: 'center', vAlign: 'bottom', color: '#1f2d3d' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: midRes, y: labelY }, hAlign: 'center', vAlign: 'bottom', color: '#1f2d3d' }
      ] }
    };
  }
};
